import { createOpenAPI } from "fumadocs-openapi/server";

// Server-side only. The schema is generated by scripts/generate-openapi.mts from the
// running `api.main.create_app()` (no server or database needed, see that script), never
// hand-written.
export const openapi = createOpenAPI({
  // A named id (rather than the bare path) since generated pages reference it directly.
  input: { myapp: "./.generated/openapi.json" },
});
